const galleryImages = [{"src": "data:image/jpeg;base64,", "caption": "Devotees gathered for darshan inside the mandir"}, {"src": "data:image/jpeg;base64,", "caption": "Sheshshayi Vishnu and Lakshmi shrine"}, {"src": "data:image/jpeg;base64,", "caption": "Lakshman Ram Janaki darbar with offerings"}, {"src": "data:image/jpeg;base64,", "caption": "Hanuman ji murti in vibrant shringar"}, {"src": "data:image/jpeg;base64,", "caption": "Ganesh ji murti at the temple entrance"}, {"src": "data:image/jpeg;base64,", "caption": "Peaceful view of the mandir campus"}, {"src": "data:image/jpeg;base64,", "caption": "Kala Bhairav ji murti inside the temple"}, {"src": "data:image/jpeg;base64,", "caption": "Sacred Shivling abhishek area"}];
  let currentGalleryIndex = 0;

  

  // Extra media loaded from /html/media
  galleryImages.push(
    { type: "video", src: "media/gallery-01.mp4"},
    { type: "video", src: "media/gallery-02.mp4"},
    { type: "video", src: "media/gallery-03.mp4"},
    { type: "video", src: "media/gallery-04.mp4"}
  );
  const extraGalleryVideos = [
    { type: "video", src: "media/gallery-07.mp4", caption: "Bagla mukhi mata aarti" },
    { type: "video", src: "media/gallery-08.mp4", caption: "Hanuman ji aarti" }
  ];
  const extraGalleryStartIndex = galleryImages.length;
  galleryImages.push(...extraGalleryVideos);

  function renderExtraGalleryVideos() {
    const masonry = document.querySelector('.gallery-masonry');
    if (!masonry) return;

    extraGalleryVideos.forEach((item, index) => {
      const figure = document.createElement('figure');
      figure.className = 'gallery-card';
      figure.onclick = function () {
        openGalleryLightbox(extraGalleryStartIndex + index);
      };

      const video = document.createElement('video');
      video.src = item.src;
      video.muted = true;
      video.playsInline = true;
      video.preload = 'metadata';

      const caption = document.createElement('figcaption');
      caption.className = 'gallery-caption';
      caption.textContent = item.caption || 'Temple Gallery Video';

      figure.appendChild(video);
      figure.appendChild(caption);
      masonry.appendChild(figure);
    });
  }

  renderExtraGalleryVideos();
  function openGalleryLightbox(index) {
    currentGalleryIndex = index;
    const lightbox = document.getElementById('galleryLightbox');
    const image = document.getElementById('galleryLightboxImage');
    const video = document.getElementById('galleryLightboxVideo');
    const caption = document.getElementById('galleryLightboxCaption');
    const item = galleryImages[currentGalleryIndex];

    const type = item.type || "image";
    if (type === "video") {
      if (image) image.style.display = "none";
      if (video) {
        video.style.display = "block";
        video.src = item.src;
        video.currentTime = 0;
        video.play().catch(() => {});
      }
    } else {
      if (video) {
        video.pause();
        video.removeAttribute("src");
        video.load();
        video.style.display = "none";
      }
      if (image) {
        image.style.display = "block";
        image.src = item.src;
        image.alt = item.caption;
      }
    }

    caption.textContent = item.caption;
    lightbox.classList.add('active');
    document.body.style.overflow = 'hidden';
  }
  function closeGalleryLightbox() {
    const lightbox = document.getElementById('galleryLightbox');
    const video = document.getElementById('galleryLightboxVideo');
    lightbox.classList.remove('active');
    document.body.style.overflow = '';
    if (video) {
      video.pause();
      video.removeAttribute("src");
      video.load();
      video.style.display = "none";
    }
  }

  function changeGalleryImage(step) {
    currentGalleryIndex = (currentGalleryIndex + step + galleryImages.length) % galleryImages.length;
    openGalleryLightbox(currentGalleryIndex);
  }

  function handleGalleryLightboxBackdrop(event) {
    if (event.target.id === 'galleryLightbox') {
      closeGalleryLightbox();
    }
  }

  document.addEventListener('keydown', function(event) {
    const lightbox = document.getElementById('galleryLightbox');
    if (!lightbox || !lightbox.classList.contains('active')) return;
    if (event.key === 'Escape') closeGalleryLightbox();
    if (event.key === 'ArrowRight') changeGalleryImage(1);
    if (event.key === 'ArrowLeft') changeGalleryImage(-1);
  });
